// End-to-end test of the real environment with podman: up, status, seed, restart with new
// credentials, down, purge. It starts containers and pulls images on first use, so it only runs
// when TRUSTIOT_DEV_E2E=1:
//   TRUSTIOT_DEV_E2E=1 bun test scripts/tests/e2e.test.ts
// It uses its own instance, state directory and random ports, so it does not touch a
// developer's running environment.
//
// Postgres serves TLS with a CA generated by `up`. The test proves that the example service
// (service-kit, rustls) connects with `verify-full` and becomes ready, and that the same
// container with another CA, or with a host name the certificate does not carry, does not.
//
// The identity service (Laysi/trustiot-v2#336) runs on the host with the settings `env` prints,
// as a developer would run `cargo run -p identity`: the test proves that the migration Job made
// `identity_app` able to log in, that the seeded dev cookie gets a token from ext_authz that the
// printed public keys verify, that a wrong cookie is refused, and that the signing key is kept
// by `down` and removed by `purge`.
import { describe, expect, test } from "bun:test";
import { createPublicKey, verify } from "node:crypto";
import { request } from "node:http";
import { createServer } from "node:net";
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { DEV_TENANT_ID, DEV_USER_ID, newCookie, SESSION_COOKIE_NAME } from "../lib/identity.ts";
import { podman, podmanOk } from "../lib/podman.ts";
import { DEV_USER, POSTGRES_DATABASE } from "../lib/secrets.ts";
import { SERVICES, platformEnv } from "../lib/services.ts";
import { namesFor, runArgs, SERVICE_PORT } from "../lib/stack.ts";
import { generateDevCertificates } from "../lib/tls.ts";

const ENABLED = process.env.TRUSTIOT_DEV_E2E === "1";
const SCRIPT = join(import.meta.dir, "..", "dev.ts");
const REPO = join(import.meta.dir, "..", "..");
// A cold cargo build of the service on a busy machine alone can take most of ten minutes.
const SLOW_MS = 1_200_000;

function freePort(): Promise<number> {
  return new Promise((resolve, reject) => {
    const server = createServer();
    server.once("error", reject);
    server.listen({ host: "127.0.0.1", port: 0 }, () => {
      const { port } = server.address() as { port: number };
      server.close(() => resolve(port));
    });
  });
}

async function dev(env: Record<string, string>, ...args: string[]) {
  const child = Bun.spawn([process.execPath, SCRIPT, ...args], {
    env: { ...process.env, ...env },
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr, code] = await Promise.all([
    new Response(child.stdout).text(),
    new Response(child.stderr).text(),
    child.exited,
  ]);
  return { stdout, stderr, code };
}

async function podmanList(...args: string[]): Promise<string[]> {
  const child = Bun.spawn(["podman", ...args], { stdout: "pipe", stderr: "pipe" });
  const out = await new Response(child.stdout).text();
  await child.exited;
  return out.split("\n").filter(Boolean);
}

/**
 * The anonymous volumes (a 64-digit hex name, which podman generates) mounted by the instance's
 * containers. The images declare `VOLUME`s the instance does not name, so each container gets
 * some; the named data volumes are the instance's own and carry its label.
 */
async function anonymousVolumes(label: string): Promise<string[]> {
  const containers = await podmanList("ps", "-a", "--filter", label, "--format", "{{.Names}}");
  if (containers.length === 0) return [];
  const mounted = await podmanList("inspect", "--format", "{{range .Mounts}}{{.Name}} {{end}}", ...containers);
  return mounted.flatMap((line) => line.split(/\s+/)).filter((name) => /^[0-9a-f]{64}$/.test(name));
}

async function volumeExists(name: string): Promise<boolean> {
  return (await podman(["volume", "exists", name])).code === 0;
}

/** KEY=value lines, as a dotenv reader or a shell `eval` takes them: single quotes are removed. */
function parseEnv(text: string): Record<string, string> {
  return Object.fromEntries(
    text
      .trim()
      .split("\n")
      .map((line) => {
        const value = line.slice(line.indexOf("=") + 1);
        return [line.slice(0, line.indexOf("=")), /^'.*'$/.test(value) ? value.slice(1, -1) : value];
      }),
  );
}

/** Builds the identity service with cargo, as `cargo run -p identity` would, and returns its path. */
async function buildIdentity(): Promise<string> {
  const child = Bun.spawn(
    ["cargo", "build", "--package", "identity", "--bin", "identity", "--message-format", "json-render-diagnostics"],
    { cwd: REPO, stdout: "pipe", stderr: "inherit" },
  );
  const [output, code] = await Promise.all([new Response(child.stdout).text(), child.exited]);
  expect(code, "cargo build of identity").toBe(0);
  for (const line of output.split("\n").reverse()) {
    if (!line.startsWith("{")) continue;
    const message = JSON.parse(line) as { reason?: string; executable?: string | null; target?: { name?: string } };
    if (message.reason === "compiler-artifact" && message.target?.name === "identity" && message.executable) {
      return message.executable;
    }
  }
  throw new Error("cargo did not report an executable for identity");
}

interface RunningIdentity {
  apiPort: number;
  /** Everything the process wrote, once it has stopped. */
  stop(): Promise<string>;
}

/**
 * Starts the identity service on the host from what `env` printed: the platform settings and the
 * key paths as they are, the database login under the names the service reads (the README of the
 * scripts says to map `TRUSTIOT_DEV_IDENTITY_DATABASE_*` this way).
 */
async function startIdentity(binary: string, settings: Record<string, string>): Promise<RunningIdentity> {
  const apiPort = await freePort();
  const healthPort = await freePort();
  const child = Bun.spawn([binary], {
    env: {
      PATH: process.env.PATH ?? "",
      ...settings,
      TRUSTIOT__DATABASE__USERNAME: settings.TRUSTIOT_DEV_IDENTITY_DATABASE_USERNAME!,
      TRUSTIOT__DATABASE__PASSWORD: settings.TRUSTIOT_DEV_IDENTITY_DATABASE_PASSWORD!,
      TRUSTIOT__HTTP__LISTEN_ADDR: `127.0.0.1:${apiPort}`,
      TRUSTIOT__HTTP__HEALTH_LISTEN_ADDR: `127.0.0.1:${healthPort}`,
      TRUSTIOT__SHUTDOWN__DRAIN_DELAY: "100ms",
    },
    stdout: "pipe",
    stderr: "pipe",
  });
  const output = Promise.all([new Response(child.stdout).text(), new Response(child.stderr).text()]).then(
    ([out, err]) => `${out}\n${err}`,
  );
  const stop = async () => {
    child.kill("SIGTERM");
    await child.exited;
    return output;
  };
  const deadline = Date.now() + 120_000;
  while ((await status(`http://127.0.0.1:${healthPort}/readyz`)) !== 200) {
    if (child.exitCode !== null || Date.now() >= deadline) {
      const log = await stop();
      throw new Error(`the identity service did not become ready:\n${log.slice(-2000)}`);
    }
    await Bun.sleep(500);
  }
  return { apiPort, stop };
}

interface Answer {
  status: number;
  /** Every header line as the server wrote it, so a repeated header shows up twice. */
  headers: [string, string][];
  body: string;
}

/** An ext_authz call: the original request's Host and Cookie, on the path under `/internal/ext-authz`. */
function extAuthz(port: number, path: string, headers: Record<string, string>): Promise<Answer> {
  return new Promise((resolve, reject) => {
    const call = request({ host: "127.0.0.1", port, path: `/internal/ext-authz${path}`, method: "GET", headers }, (response) => {
      let body = "";
      response.setEncoding("utf8");
      response.on("data", (chunk) => (body += chunk));
      response.on("end", () => {
        const headers: [string, string][] = [];
        for (let index = 0; index < response.rawHeaders.length; index += 2) {
          headers.push([response.rawHeaders[index]!.toLowerCase(), response.rawHeaders[index + 1]!]);
        }
        resolve({ status: response.statusCode ?? 0, headers, body });
      });
    });
    call.once("error", reject);
    call.end();
  });
}

/** Verifies a token against the printed JWK Set, the way a service does. */
function verifyToken(token: string, keys: string) {
  const [header, payload, signature] = token.split(".") as [string, string, string];
  const protectedHeader = JSON.parse(Buffer.from(header, "base64url").toString()) as { alg: string; typ: string; kid: string };
  const jwk = (JSON.parse(keys) as { keys: { kty: string; crv: string; kid: string; x: string }[] }).keys.find(
    (key) => key.kid === protectedHeader.kid,
  );
  expect(jwk, "the token's kid is in the printed key set").toBeDefined();
  const publicKey = createPublicKey({ key: { kty: jwk!.kty, crv: jwk!.crv, x: jwk!.x }, format: "jwk" });
  return {
    protectedHeader,
    signatureValid: verify(null, Buffer.from(`${header}.${payload}`), publicKey, Buffer.from(signature, "base64url")),
    claims: JSON.parse(Buffer.from(payload, "base64url").toString()) as {
      iss: string;
      sub: string;
      aud: string;
      iat: number;
      exp: number;
      tenant?: { id: string; role: string };
    },
  };
}

/** The ext_authz contract of services/identity/README.md for the seeded dev session. */
async function checkExtAuthz(port: number, cookie: string, keys: string): Promise<void> {
  const allowed = await extAuthz(port, "/api/anything", { host: "localhost", cookie });
  expect(allowed.status, allowed.body).toBe(200);
  const identityHeaders = allowed.headers.filter(([name]) => name === "x-internal-identity");
  expect(identityHeaders, "exactly one x-internal-identity").toHaveLength(1);
  const { protectedHeader, signatureValid, claims } = verifyToken(identityHeaders[0]![1], keys);
  expect(protectedHeader).toMatchObject({ alg: "EdDSA", typ: "internal-identity+jwt" });
  expect(signatureValid, "the printed public key verifies the token").toBe(true);
  expect(claims).toMatchObject({
    iss: "identity",
    sub: DEV_USER_ID,
    aud: "assets",
    tenant: { id: DEV_TENANT_ID, role: "admin" },
  });
  expect(claims.exp - claims.iat).toBe(60);

  // Another well-formed cookie, no cookie, and a malformed one are all 401 without an identity.
  for (const cookieHeader of [`${SESSION_COOKIE_NAME}=${newCookie()}`, undefined, `${SESSION_COOKIE_NAME}=short`]) {
    const refused = await extAuthz(port, "/api/anything", {
      host: "localhost",
      ...(cookieHeader === undefined ? {} : { cookie: cookieHeader }),
    });
    expect(refused.status, `cookie ${cookieHeader === undefined ? "absent" : "invalid"}`).toBe(401);
    expect(refused.headers.filter(([name]) => name === "x-internal-identity")).toEqual([]);
  }
  // A valid session for a host and path the route table does not know is 403.
  const unrouted = await extAuthz(port, "/api/anything", { host: "other.example.com", cookie });
  expect(unrouted.status).toBe(403);
  expect(unrouted.headers.filter(([name]) => name === "x-internal-identity")).toEqual([]);
}

/** Runs one query as the dev superuser over the container's socket; one result line per row. */
async function psql(instance: string, sql: string): Promise<string[]> {
  const output = await podmanOk([
    "exec",
    namesFor(instance).container("postgres"),
    "psql",
    `--username=${DEV_USER}`,
    `--dbname=${POSTGRES_DATABASE}`,
    "--no-psqlrc",
    "--tuples-only",
    "--no-align",
    "--command",
    sql,
  ]);
  return output.split("\n").filter(Boolean);
}

/** What the services read: the dev cookie from `seed`'s output. */
function seededCookie(output: string): string {
  const match = /^ {2}Cookie: (__Host-trustiot-session=[A-Za-z0-9_-]{43})$/m.exec(output);
  expect(match, "seed prints the cookie").not.toBeNull();
  return match![1]!;
}

/** The files under `dir` (recursively) whose content contains `needle`. */
function filesWith(dir: string, needle: string): string[] {
  const found: string[] = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) found.push(...filesWith(path, needle));
    else if (readFileSync(path, "utf8").includes(needle)) found.push(path);
  }
  return found;
}

async function gitStatus(): Promise<string> {
  const child = Bun.spawn(["git", "status", "--porcelain", "--ignored"], {
    cwd: REPO,
    stdout: "pipe",
    stderr: "pipe",
  });
  const out = await new Response(child.stdout).text();
  await child.exited;
  return out;
}

async function status(url: string): Promise<number | undefined> {
  try {
    return (await fetch(url, { signal: AbortSignal.timeout(3000) })).status;
  } catch {
    return undefined;
  }
}

interface Probe {
  /** The service container in the dev network, with its own Postgres host name and CA. */
  host: string;
  caPem: string;
}

/**
 * Starts the example service image the way `up` does, but with a chosen Postgres host name and
 * CA, and returns its published port. The container is labelled with the instance, so `purge`
 * removes it even when the test stops early.
 */
async function startProbe(
  instance: string,
  state: { credentials: { postgres: { database: string }; services: Record<string, { user: string; password: string }> } },
  name: string,
  probe: Probe,
  scratch: string,
): Promise<{ container: string; port: number }> {
  const service = SERVICES.find((candidate) => candidate.database)!;
  const login = state.credentials.services[service.name]!;
  const port = await freePort();
  const create = runArgs(instance, {
    component: name,
    image: namesFor(instance).image(service.name),
    memory: "256m",
    publish: [[port, SERVICE_PORT]],
    env: {
      ...platformEnv(state.credentials.postgres.database),
      ...service.env,
      TRUSTIOT_POSTGRES_HOST: probe.host,
      TRUSTIOT_POSTGRES_CA_FILE: "/ca.crt",
      TRUSTIOT__DATABASE__USERNAME: login.user,
      TRUSTIOT__DATABASE__PASSWORD: login.password,
    },
  }).filter((argument) => argument !== "--detach");
  create[0] = "create";
  const container = namesFor(instance).container(name);
  await podmanOk(create);
  const caFile = join(scratch, `${name}.crt`);
  await Bun.write(caFile, probe.caPem);
  await podmanOk(["cp", caFile, `${container}:/ca.crt`]);
  await podmanOk(["start", container]);
  return { container, port };
}

describe.skipIf(!ENABLED)("the dev environment with podman", () => {
  test(
    "starts, passes every check, seeds, rotates credentials, stops and purges without leftovers",
    async () => {
      const instance = `e2e-${Math.random().toString(36).slice(2, 8)}`;
      const state = mkdtempSync(join(tmpdir(), "trustiot-dev-e2e-"));
      const env = {
        TRUSTIOT_DEV_INSTANCE: instance,
        XDG_STATE_HOME: state,
        TRUSTIOT_DEV_POSTGRES_PORT: String(await freePort()),
        TRUSTIOT_DEV_CLICKHOUSE_PORT: String(await freePort()),
        TRUSTIOT_DEV_MQTT_PORT: String(await freePort()),
      };
      const label = `label=io.laysi.trustiot-dev.instance=${instance}`;
      const instanceDir = join(state, "trustiot-v2", "dev", instance);
      const stateFile = join(instanceDir, "state.json");
      const caFile = join(instanceDir, "tls", "ca.crt");
      const signingKeyFile = join(instanceDir, "identity", "signing-key.pem");
      // Built first, so the build directory exists before the tree is compared at the end.
      const identityBinary = await buildIdentity();
      const treeBefore = await gitStatus();
      try {
        const first = await dev(env, "up");
        // cargo reports its progress on stderr; an error would also exit non-zero.
        expect(first.stderr).not.toMatch(/^error/m);
        expect(first.code).toBe(0);
        expect(first.stdout).toContain("every check passed");
        expect(first.stdout).not.toContain("FAIL");
        // The TLS checks ran and passed as part of up.
        for (const name of [
          "postgres: published port refuses a connection without TLS",
          "postgres: published port demands a password over TLS",
          "postgres: certificate of another CA refused",
          "postgres: certificate for another host name refused",
          "postgres: login over TLS and Apache AGE",
        ]) {
          expect(first.stdout, name).toContain(`ok   ${name}`);
        }
        // The service is ready only with a verify-full connection to Postgres.
        const readiness = SERVICES.map((service) => `${service.name}: GET /readyz`);
        for (const name of readiness) expect(first.stdout).toContain(`ok   ${name}`);

        const firstState = JSON.parse(readFileSync(stateFile, "utf8"));
        expect(statSync(stateFile).mode & 0o777).toBe(0o600);
        const firstCa = readFileSync(caFile, "utf8");
        expect(firstCa).toContain("BEGIN CERTIFICATE");
        expect(firstCa).not.toContain("PRIVATE KEY");
        // The only private key in the state directory is the identity signing key (the Postgres
        // server key lives in a volume), owner-only, in the identity directory.
        expect(filesWith(instanceDir, "PRIVATE KEY")).toEqual([signingKeyFile]);
        expect(statSync(signingKeyFile).mode & 0o777).toBe(0o600);
        expect(statSync(join(instanceDir, "identity")).mode & 0o777).toBe(0o700);
        const firstKey = readFileSync(signingKeyFile, "utf8");
        const signingKeyBody = firstKey.split("\n")[1]!;
        expect(signingKeyBody.length).toBeGreaterThan(20);
        // The migration Job ran, with the same code as in a cluster, and left identity_app able to
        // log in with the password it generated (the role is NOLOGIN without a bound Secret).
        expect(first.stdout).toContain("running the migration Job (tools/migrate)");
        expect(first.stdout).toContain("migration Job finished");
        expect(firstState.credentials.services.identity.user).toBe("identity_app");
        expect(firstState.credentials.services.identity.password).toMatch(/^[0-9a-f]{64}$/);
        const roles = await psql(instance, "SELECT rolname || ':' || rolcanlogin || ':' || rolsuper FROM pg_roles WHERE rolname LIKE 'identity_%' OR rolname = 'trustiot_owner' ORDER BY 1");
        // identity_platform exists because identity writes outbox events (Laysi/trustiot-v2#65); no
        // Secret is bound to it, so it stays NOLOGIN like every role the dev environment does not run.
        expect(roles).toEqual(["identity_app:true:false", "identity_owner:false:false", "identity_platform:false:false", "trustiot_owner:true:false"]);
        expect(await psql(instance, "SELECT pg_get_userbyid(datdba) FROM pg_database WHERE datname = 'trustiot'")).toEqual(["trustiot_owner"]);

        const printed = await dev(env, "env");
        expect(printed.code).toBe(0);
        const settings = parseEnv(printed.stdout);
        expect(settings.TRUSTIOT_POSTGRES_SSLMODE).toBe("verify-full");
        expect(settings.TRUSTIOT_POSTGRES_HOST).toBe("127.0.0.1");
        expect(settings.TRUSTIOT_POSTGRES_PORT).toBe(env.TRUSTIOT_DEV_POSTGRES_PORT);
        expect(settings.TRUSTIOT_POSTGRES_CA_FILE).toBe(caFile);
        expect(settings.PGSSLMODE).toBe("verify-full");
        expect(settings.PGSSLROOTCERT).toBe(caFile);
        // The identity service's settings: the public keys for every service, the key's path (not
        // the key), the routes, and the identity_app login the Job generated.
        expect(settings.TRUSTIOT_IDENTITY_SIGNING_KEY_FILE).toBe(signingKeyFile);
        expect(JSON.parse(settings.TRUSTIOT_INTERNAL_IDENTITY_KEYS!).keys).toHaveLength(1);
        expect(JSON.parse(settings.TRUSTIOT_INGRESS_ROUTES!)[0].host).toBe("localhost");
        expect(settings.TRUSTIOT_DEV_IDENTITY_DATABASE_USERNAME).toBe("identity_app");
        expect(settings.TRUSTIOT_DEV_IDENTITY_DATABASE_PASSWORD).toBe(firstState.credentials.services.identity.password);
        expect(printed.stdout).not.toContain("PRIVATE KEY");
        expect(printed.stdout).not.toContain(signingKeyBody);

        const status1 = await dev(env, "status");
        expect(status1.code).toBe(0);
        expect(status1.stdout).toContain("all checks passed");
        expect(status1.stdout).toContain("ok   identity: signing key");

        const seedRuns: string[] = [];
        for (let round = 0; round < 2; round++) {
          const seeded = await dev(env, "seed");
          expect(seeded.code).toBe(0);
          expect(seeded.stdout).toContain("seed verified: 2 machines (table and graph), 240 telemetry rows");
          seedRuns.push(seeded.stdout + seeded.stderr);
        }
        // Seeding again keeps the dev session: the same cookie, created once.
        const cookie = seededCookie(seedRuns[0]!);
        expect(seededCookie(seedRuns[1]!)).toBe(cookie);
        expect(seedRuns[0]).toContain("created the identity dev session");
        expect(seedRuns[1]).toContain("kept the identity dev session");
        expect(readFileSync(join(instanceDir, "identity", "dev-session-cookie"), "utf8").trim()).toBe(
          cookie.slice(cookie.indexOf("=") + 1),
        );
        expect(statSync(join(instanceDir, "identity", "dev-session-cookie")).mode & 0o777).toBe(0o600);
        expect(await psql(instance, "SELECT count(*) FROM identity.sessions")).toEqual(["1"]);

        // The identity service, started on the host from what env printed: ready, and ext_authz
        // hands the seeded cookie's user a token that the printed public keys verify.
        const identity = await startIdentity(identityBinary, settings);
        let identityLog: string;
        try {
          await checkExtAuthz(identity.apiPort, cookie, settings.TRUSTIOT_INTERNAL_IDENTITY_KEYS!);
        } finally {
          identityLog = await identity.stop();
        }
        // Neither key material nor a password reaches the identity service's log.
        for (const secret of [signingKeyBody, firstState.credentials.services.identity.password, cookie.slice(cookie.indexOf("=") + 1)]) {
          expect(identityLog).not.toContain(secret);
        }

        // A service container with the right CA and name is ready; with another CA, or a host
        // name that the certificate does not carry, it stays unready although it runs.
        const names = namesFor(instance);
        const probes: Record<string, Probe> = {
          "probe-control": { host: "postgres", caPem: firstCa },
          "probe-wrong-ca": { host: "postgres", caPem: generateDevCertificates("wrong").caCertificate },
          "probe-wrong-host": { host: names.container("postgres"), caPem: firstCa },
        };
        const started: Record<string, { container: string; port: number }> = {};
        for (const [name, probe] of Object.entries(probes)) {
          started[name] = await startProbe(instance, firstState, name, probe, state);
        }
        const deadline = Date.now() + 90_000;
        while ((await status(`http://127.0.0.1:${started["probe-control"]!.port}/readyz`)) !== 200) {
          expect(Date.now(), "the control probe never became ready").toBeLessThan(deadline);
          await Bun.sleep(1000);
        }
        // By now the others have had as long as the control to connect.
        for (const name of ["probe-wrong-ca", "probe-wrong-host"]) {
          const { port, container } = started[name]!;
          expect(await status(`http://127.0.0.1:${port}/healthz`), `${name} runs`).toBe(200);
          expect(await status(`http://127.0.0.1:${port}/readyz`), `${name} is not ready`).toBe(503);
          const logs = await podman(["logs", container]);
          expect(logs.stdout + logs.stderr, name).not.toContain(firstState.credentials.services["example-service"].password);
        }
        await podmanOk(["rm", "--force", "--volumes", "--time", "1", ...Object.values(started).map((one) => one.container)]);

        // No secret on a terminal during up, status or seed.
        const output = [first, status1].map((run) => run.stdout + run.stderr).join("\n");
        for (const secret of [
          firstState.credentials.postgres.password,
          firstState.credentials.clickhouse.password,
          firstState.credentials.mqtt.password,
          firstState.credentials.services["example-service"].password,
          firstState.credentials.services.identity.password,
          signingKeyBody,
        ]) {
          expect(output).not.toContain(secret);
          // seed prints the dev cookie, as asked, and nothing else that is secret.
          expect(seedRuns.join("\n")).not.toContain(secret);
        }

        expect((await podmanList("ps", "--filter", label, "--format", "{{.Names}}")).length).toBe(3 + SERVICES.length);
        // Laysi/trustiot-v2#334: down removes the containers' anonymous volumes with them.
        const anonymous = await anonymousVolumes(label);
        expect(anonymous.length, "the images declare volumes the instance does not name").toBeGreaterThan(0);
        expect((await dev(env, "down")).code).toBe(0);
        for (const volume of anonymous) expect(await volumeExists(volume), `anonymous volume ${volume}`).toBe(false);
        expect(await podmanList("ps", "-a", "--filter", label, "--format", "{{.Names}}")).toEqual([]);
        expect(await podmanList("network", "ls", "--filter", label, "--format", "{{.Name}}")).toEqual([]);
        // The data survives down ...
        const volumes = await podmanList("volume", "ls", "--filter", label, "--format", "{{.Name}}");
        expect(volumes.length).toBeGreaterThan(0);
        // ... but the certificates and the server key do not.
        expect(volumes.filter((volume) => /postgres-(config|ca)$/.test(volume))).toEqual([]);
        expect(existsSync(caFile)).toBe(false);
        expect(existsSync(stateFile)).toBe(false);
        // The identity signing key (and the cookie of the session in the kept data) stay: down
        // leaves exactly the identity directory.
        expect(readdirSync(instanceDir)).toEqual(["identity"]);
        expect(readFileSync(signingKeyFile, "utf8")).toBe(firstKey);
        expect(statSync(signingKeyFile).mode & 0o777).toBe(0o600);

        // ... and the next up uses new credentials and a new CA against the old data.
        const second = await dev(env, "up");
        expect(second.code).toBe(0);
        expect(second.stdout).toContain("every check passed");
        const secondState = JSON.parse(readFileSync(stateFile, "utf8"));
        expect(secondState.credentials.postgres.password).not.toBe(firstState.credentials.postgres.password);
        expect(secondState.credentials.clickhouse.password).not.toBe(firstState.credentials.clickhouse.password);
        expect(secondState.credentials.mqtt.password).not.toBe(firstState.credentials.mqtt.password);
        expect(secondState.credentials.services["example-service"].password).not.toBe(
          firstState.credentials.services["example-service"].password,
        );
        expect(readFileSync(caFile, "utf8")).not.toBe(firstCa);
        const reseeded = await dev(env, "seed");
        expect(reseeded.stdout).toContain("seed verified: 2 machines (table and graph), 240 telemetry rows");
        expect(existsSync(join(instanceDir, "tls"))).toBe(true);

        // The key was kept, so the public keys are the same; the Job set a new identity_app
        // password; the session in the kept data still works with the same cookie.
        expect(second.stdout).toContain("identity signing key: kept");
        expect(readFileSync(signingKeyFile, "utf8")).toBe(firstKey);
        expect(secondState.credentials.services.identity.password).not.toBe(firstState.credentials.services.identity.password);
        expect(seededCookie(reseeded.stdout)).toBe(cookie);
        expect(reseeded.stdout).toContain("kept the identity dev session");
        const secondSettings = parseEnv((await dev(env, "env")).stdout);
        expect(secondSettings.TRUSTIOT_INTERNAL_IDENTITY_KEYS).toBe(settings.TRUSTIOT_INTERNAL_IDENTITY_KEYS);
        const again = await startIdentity(identityBinary, secondSettings);
        try {
          await checkExtAuthz(again.apiPort, cookie, secondSettings.TRUSTIOT_INTERNAL_IDENTITY_KEYS!);
        } finally {
          await again.stop();
        }
      } finally {
        const purged = await dev(env, "purge");
        expect(purged.code).toBe(0);
        // Purge removes the certificates and the keys with the rest of the state, and the
        // sessions with the data volume.
        expect(existsSync(caFile)).toBe(false);
        expect(existsSync(signingKeyFile)).toBe(false);
        expect(existsSync(join(instanceDir, "identity"))).toBe(false);
        expect(existsSync(join(instanceDir, "tls"))).toBe(false);
        expect(existsSync(instanceDir)).toBe(false);
        rmSync(state, { recursive: true, force: true });
      }
      expect(await podmanList("ps", "-a", "--filter", label, "--format", "{{.Names}}")).toEqual([]);
      expect(await podmanList("volume", "ls", "--filter", label, "--format", "{{.Name}}")).toEqual([]);
      expect(await podmanList("network", "ls", "--filter", label, "--format", "{{.Name}}")).toEqual([]);
      // Nothing generated landed in the repository.
      expect(await gitStatus()).toBe(treeBefore);
    },
    SLOW_MS,
  );
});
